package com.bank.flush.service;

import com.bank.flush.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.FlushModeType;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.util.List;

@Service
@Slf4j
public class AdjustmentService {

    @PersistenceContext
    private EntityManager em;

    // AUTO (default): the pending balance change IS visible to the query below
    @Transactional
    public int zeroBalanceThenCount(String id) {
        Account acct = em.find(Account.class, id);
        acct.setBalance(BigDecimal.ZERO);  // pending change, not flushed yet

        // FlushModeType.AUTO → Hibernate flushes before this query runs
        List<Account> zeros = em.createQuery(
                "select a from Account a where a.balance = 0", Account.class)
                .setFlushMode(FlushModeType.AUTO)
                .getResultList();
        log.info("AUTO: query sees the pending zero balance → count = {}", zeros.size());
        return zeros.size();  // includes the just-zeroed account
    }
}
