package com.bank.flush.service;

import com.bank.flush.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.FlushModeType;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.util.List;

@Service
@Slf4j
public class DashboardService {

    @PersistenceContext
    private EntityManager em;

    // COMMIT: skip the auto-flush before each read query (fewer flushes, faster reads)
    @Transactional(readOnly = true)
    public BigDecimal totalBalance() {
        em.setFlushMode(FlushModeType.COMMIT);  // do not flush before queries
        List<BigDecimal> balances = em.createQuery(
                "select a.balance from Account a", BigDecimal.class).getResultList();
        BigDecimal total = balances.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info("COMMIT mode: {} queries ran without pre-query flushes", balances.size());
        return total;
    }
}
